import{_ as e,c as a,o as n,al as o}from"./chunks/framework.CFRQwSJO.js";const u=JSON.parse('{"title":"React Fiber 架构与 Diff 算法深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/React/fiber-diff.md","filePath":"frontend/React/fiber-diff.md","lastUpdated":1784879784000}'),r={name:"frontend/React/fiber-diff.md"};function s(d,t,i,l,c,p){return n(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="react-fiber-架构与-diff-算法深度解析" tabindex="-1">React Fiber 架构与 Diff 算法深度解析 <a class="header-anchor" href="#react-fiber-架构与-diff-算法深度解析" aria-label="Permalink to &quot;React Fiber 架构与 Diff 算法深度解析&quot;">​</a></h1><blockquote><p>本文围绕 <strong>&quot;Fiber 是什么 → 双缓冲机制 → 协调流程 → Diff 策略&quot;</strong> 这条主线，帮你建立对 React 内部调和过程的完整认知。 背景：JavaScript 执行和浏览器渲染<strong>共享同一个主线程</strong>。浏览器通过事件循环（Event Loop）交替处理 JavaScript 任务和渲染任务，长 JavaScript 任务会阻塞渲染，造成页面卡顿。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#一什么是-fiber核心字段拆解">一、什么是 Fiber？核心字段拆解</a></li><li><a href="#二双缓冲树机制">二、双缓冲树机制</a></li><li><a href="#三协调流程总览beginwork--completework">三、协调流程总览：beginWork → completeWork</a></li><li><a href="#四单节点-diff--reconcilesingleelement">四、单节点 Diff —— reconcileSingleElement</a></li><li><a href="#五多节点-diff--reconcilechildrenarray-两轮遍历">五、多节点 Diff —— reconcileChildrenArray 两轮遍历</a></li><li><a href="#六key-的本质作用">六、key 的本质作用</a></li><li><a href="#七首次挂载-vs-更新对比总结">七、首次挂载 vs 更新对比总结</a></li><li><a href="#-面试回答完整版10分版">🎤 面试回答完整版（10分版）</a></li></ul><hr><h2 id="一、什么是-fiber-核心字段拆解" tabindex="-1">一、什么是 Fiber？核心字段拆解 <a class="header-anchor" href="#一、什么是-fiber-核心字段拆解" aria-label="Permalink to &quot;一、什么是 Fiber？核心字段拆解&quot;">​</a></h2><p><strong>Fiber</strong> 是 React 16 重写内核后引入的核心数据结构，本质是一个 <strong>JavaScript 对象</strong>。每个 React 组件（或 DOM 节点）都对应一个 Fiber 节点，它在整个组件的生命周期内<strong>持久存在</strong>，是 React 协调引擎真正操作的对象。</p><blockquote><p>⚠️ <strong>注意</strong>：React Element 每次渲染都会重新生成，但 Fiber 节点不会——它被复用并持续更新。</p></blockquote><h3 id="fiber-节点核心字段" tabindex="-1">Fiber 节点核心字段 <a class="header-anchor" href="#fiber-节点核心字段" aria-label="Permalink to &quot;Fiber 节点核心字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">分组</th><th>字段</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">🏷️ 身份</td><td><code>type</code></td><td>组件函数本身（函数组件）或字符串 <code>&#39;div&#39;</code>（宿主节点）。Diff 的关键依据之一。</td></tr><tr><td style="text-align:center;">🏷️ 身份</td><td><code>key</code></td><td>用户显式设置的唯一标识，优先于 type 进行列表项匹配。</td></tr><tr><td style="text-align:center;">🏷️ 身份</td><td><code>tag</code></td><td>Fiber 类型枚举：函数组件（0）、类组件（1）、HostComponent（5，即原生 DOM 节点）等。</td></tr><tr><td style="text-align:center;">📦 状态</td><td><code>pendingProps</code></td><td>本次渲染即将使用的新 props，由父组件传入或 React Element 提供。</td></tr><tr><td style="text-align:center;">📦 状态</td><td><code>memoizedState</code></td><td>函数组件的 Hook 链表头节点；或类组件的 <code>this.state</code>。上次渲染后的已确认状态。</td></tr><tr><td style="text-align:center;">📦 状态</td><td><code>memoizedProps</code></td><td>上次渲染后已确认的 props，用于本次与 pendingProps 对比。</td></tr><tr><td style="text-align:center;">⚡ 副作用</td><td><code>flags</code>（effectTag）</td><td>标记本节点需要在 Commit 阶段进行什么 DOM 操作：Placement（插入）、Update（更新）、Deletion（删除）。</td></tr><tr><td style="text-align:center;">⚡ 副作用</td><td><code>updateQueue</code></td><td>待处理的状态更新队列，<code>setState</code> 产生的 Update 对象会挂载在这里等待处理。</td></tr><tr><td style="text-align:center;">🌳 树结构</td><td><code>return</code></td><td>指向父 Fiber 节点（注意：不是 <code>parent</code>，React 历史命名习惯）。</td></tr><tr><td style="text-align:center;">🌳 树结构</td><td><code>child</code></td><td>指向第一个子 Fiber 节点。</td></tr><tr><td style="text-align:center;">树结构</td><td><code>sibling</code></td><td>指向下一个兄弟 Fiber 节点。通过 <code>child → sibling → sibling</code> 链表表达多个子节点。</td></tr><tr><td style="text-align:center;">🔄 双缓冲</td><td><code>alternate</code></td><td>指向另一棵树中对应的 Fiber 节点（current ↔ workInProgress 互相引用）。</td></tr><tr><td style="text-align:center;">🔄 双缓冲</td><td><code>stateNode</code></td><td>类组件实例（<code>this</code>）、函数组件为 <code>null</code>、DOM 节点为真实 DOM 引用。</td></tr></tbody></table><blockquote><p>💡 Fiber 节点通过 <code>return / child / sibling</code> 三个指针把整棵组件树表示成一个<strong>单链表</strong>，这让 React 可以随时中断遍历，并在之后恢复——这是并发模式（Concurrent Mode）可中断渲染的基础。</p></blockquote><hr><h2 id="二、双缓冲树机制" tabindex="-1">二、双缓冲树机制 <a class="header-anchor" href="#二、双缓冲树机制" aria-label="Permalink to &quot;二、双缓冲树机制&quot;">​</a></h2><p>React 内部始终维护<strong>两棵 Fiber 树</strong>：</p><ul><li><strong>current 树</strong>：当前屏幕上正在显示的内容所对应的 Fiber 树，<code>FiberRoot.current</code> 指向它的根节点。</li><li><strong>workInProgress（WIP）树</strong>：正在构建中的、描述&quot;下一帧&quot;内容的 Fiber 树。</li></ul><p>当一次更新完成、WIP 树被 Commit 到 DOM 后，<code>FiberRoot.current</code> 会切换指向 WIP 树，原来的 current 树则成为下一次更新的&quot;旧树&quot;。这种&quot;乒乓切换&quot;的设计就叫做<strong>双缓冲（Double Buffering）</strong>。</p><h3 id="双缓冲工作示意图" tabindex="-1">双缓冲工作示意图 <a class="header-anchor" href="#双缓冲工作示意图" aria-label="Permalink to &quot;双缓冲工作示意图&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>current 树（屏幕上正在显示）        workInProgress 树（正在构建）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  FiberRoot                          FiberRoot</span></span>
<span class="line"><span>    └─ App                             └─ App</span></span>
<span class="line"><span>       ├─ Header                          ├─ Header</span></span>
<span class="line"><span>       └─ Content                         └─ Content</span></span>
<span class="line"><span>          └─ List (旧 props)                 └─ List (新 props 🔄)</span></span>
<span class="line"><span>              ↑                                  ↑</span></span>
<span class="line"><span>              └────────── alternate 互指 ─────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commit 完成后 → FiberRoot.current 切换指向 WIP 树</span></span>
<span class="line"><span>→ 原 current 树变成下一次的&quot;旧树&quot;</span></span></code></pre></div><h3 id="完整的指针切换流程" tabindex="-1">完整的指针切换流程 <a class="header-anchor" href="#完整的指针切换流程" aria-label="Permalink to &quot;完整的指针切换流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>WIP 树构建完成 → Commit 写入 DOM → FiberRoot.current = WIP → 原 current 变成下次的&quot;旧树&quot;</span></span></code></pre></div><blockquote><p>⚠️ <strong>为什么这样设计？</strong> 双缓冲确保了&quot;在建&quot;和&quot;在用&quot;互不干扰，即使 Render 阶段被中断重来（并发模式），当前屏幕也不受影响；Commit 阶段只需一次原子性切换，避免用户看到中间状态。</p></blockquote><hr><h2 id="三、协调流程总览-beginwork-→-completework" tabindex="-1">三、协调流程总览：beginWork → completeWork <a class="header-anchor" href="#三、协调流程总览-beginwork-→-completework" aria-label="Permalink to &quot;三、协调流程总览：beginWork → completeWork&quot;">​</a></h2><p>React 的协调（Reconciliation）过程由 <code>workLoopSync</code>（同步）或 <code>workLoopConcurrent</code>（并发）驱动，本质是对 Fiber 树进行<strong>深度优先遍历</strong>，分两个阶段处理每个节点。</p><h3 id="beginwork-向下-·-入" tabindex="-1">beginWork（向下 · 入） <a class="header-anchor" href="#beginwork-向下-·-入" aria-label="Permalink to &quot;beginWork（向下 · 入）&quot;">​</a></h3><p>从根节点开始，逐层深入子节点：</p><ol><li><strong>接收当前 Fiber 节点</strong> — 根据 <code>fiber.tag</code> 判断类型（函数组件、类组件、HostComponent 等）</li><li><strong>执行组件函数 / render</strong> — 函数组件：调用函数体，执行 Hooks；类组件：调用 <code>render()</code>；宿主节点：直接处理 props</li><li><strong>reconcileChildren（Diff）</strong> — 拿到返回的 React Element，与旧的子 Fiber 做对比，生成新的子 Fiber 链表，挂到 <code>workInProgress.child</code></li><li><strong>返回第一个子节点</strong> — 工作循环继续向下处理子节点，直到叶子节点（<code>child === null</code>）</li></ol><h3 id="completework-向上-·-出" tabindex="-1">completeWork（向上 · 出） <a class="header-anchor" href="#completework-向上-·-出" aria-label="Permalink to &quot;completeWork（向上 · 出）&quot;">​</a></h3><p>到达叶子节点后，开始向上回溯：</p><ol><li><strong>到达叶子节点后触发</strong> — 当 <code>beginWork</code> 返回 <code>null</code>（无子节点），开始回溯</li><li><strong>处理宿主节点的 DOM 操作</strong> — 对于 <code>HostComponent</code>：首次创建 DOM 实例，或标记属性变更（写入 <code>flags</code>）</li><li><strong>收集副作用（effectList）</strong> — 将有 <code>flags</code> 标记的节点收集到父节点的副作用链表，向上冒泡</li><li><strong>转向兄弟节点或继续回溯</strong> — 有 <code>sibling</code> → 对兄弟节点继续 beginWork；否则向 <code>return</code>（父节点）回溯</li></ol><h3 id="遍历顺序示例" tabindex="-1">遍历顺序示例 <a class="header-anchor" href="#遍历顺序示例" aria-label="Permalink to &quot;遍历顺序示例&quot;">​</a></h3><p>以 <code>App → A → A1 → A2 → B</code> 这棵树为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>beginWork(App) → beginWork(A) → beginWork(A1) → completeWork(A1)</span></span>
<span class="line"><span>→ beginWork(A2) → completeWork(A2) → completeWork(A)</span></span>
<span class="line"><span>→ beginWork(B) → completeWork(B) → completeWork(App)</span></span></code></pre></div><blockquote><p>💡 <code>beginWork</code> 阶段完成的是&quot;判断与标记&quot;，<code>completeWork</code> 完成的是&quot;收集与准备&quot;。整个 Render 阶段结束后，所有需要做的 DOM 操作都已被收集，Commit 阶段按清单执行即可。</p></blockquote><hr><h2 id="四、单节点-diff-——-reconcilesingleelement" tabindex="-1">四、单节点 Diff —— reconcileSingleElement <a class="header-anchor" href="#四、单节点-diff-——-reconcilesingleelement" aria-label="Permalink to &quot;四、单节点 Diff —— reconcileSingleElement&quot;">​</a></h2><p>当组件的 <code>render</code> 返回<strong>单个 React Element</strong>（非数组）时，React 调用 <code>reconcileSingleElement</code>。</p><p><strong>核心逻辑</strong>：在旧的子 Fiber 链表中寻找能被<strong>复用</strong>的节点，判断条件依次为 <code>key</code> 和 <code>type</code>。</p><h3 id="决策流程" tabindex="-1">决策流程 <a class="header-anchor" href="#决策流程" aria-label="Permalink to &quot;决策流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>新 React Element（render 返回值）</span></span>
<span class="line"><span>  → 遍历旧子 Fiber 链表</span></span>
<span class="line"><span>    → key 相同？</span></span>
<span class="line"><span>      ├─ ❌ 不同 → 标记旧 Fiber 为 Deletion（删除），继续遍历下一个兄弟</span></span>
<span class="line"><span>      │             → 全部遍历后仍无匹配 → createFiberFromElement 全新创建</span></span>
<span class="line"><span>      └─ ✅ 相同 → 再判断 type</span></span>
<span class="line"><span>          ├─ type 也相同 → useFiber（createWorkInProgress）→ ✅ 节点复用</span></span>
<span class="line"><span>          └─ type 不同   → key 相同说明是同一&quot;位置&quot;，但类型变了</span></span>
<span class="line"><span>                           → 删除旧 Fiber 及其所有兄弟 → createFiberFromElement 全新创建</span></span></code></pre></div><h3 id="复用-vs-新建的代价对比" tabindex="-1">复用 vs 新建的代价对比 <a class="header-anchor" href="#复用-vs-新建的代价对比" aria-label="Permalink to &quot;复用 vs 新建的代价对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>复用节点 ✅</th><th>新建节点 ❌</th></tr></thead><tbody><tr><td>状态</td><td>仅更新 pendingProps</td><td>全部重建，状态丢失</td></tr><tr><td>DOM</td><td>仅属性变更</td><td>需要 DOM 插入（mount）</td></tr><tr><td>生命周期</td><td>无额外触发</td><td>会触发 unmount 生命周期</td></tr></tbody></table><blockquote><p>⚠️ <strong>关键结论</strong>：判断条件是 <strong>key 优先，type 其次</strong>。key 不同时，React 不会再判断 type——直接认为这不是同一个节点。这就是为什么 key 写错会导致组件状态意外丢失。</p></blockquote><hr><h2 id="五、多节点-diff-——-reconcilechildrenarray-两轮遍历" tabindex="-1">五、多节点 Diff —— reconcileChildrenArray 两轮遍历 <a class="header-anchor" href="#五、多节点-diff-——-reconcilechildrenarray-两轮遍历" aria-label="Permalink to &quot;五、多节点 Diff —— reconcileChildrenArray 两轮遍历&quot;">​</a></h2><p>当 <code>render</code> 返回的是<strong>数组</strong>（多个子节点）时，React 使用 <code>reconcileChildrenArray</code>，通过<strong>两轮遍历</strong>处理新旧节点列表。</p><blockquote><p>💡 React 的列表 Diff <strong>不使用传统的最长公共子序列（LCS）算法</strong>，而是针对&quot;大多数更新是顺序不变的小变动&quot;这一实际场景，做了贪心优化。</p></blockquote><h3 id="第一轮-顺序遍历-处理可预测的变化" tabindex="-1">第一轮：顺序遍历，处理可预测的变化 <a class="header-anchor" href="#第一轮-顺序遍历-处理可预测的变化" aria-label="Permalink to &quot;第一轮：顺序遍历，处理可预测的变化&quot;">​</a></h3><ol><li><strong>同时从头开始遍历新旧两个列表</strong> — 按索引位置逐个比较 <code>newChildren[i]</code> 与旧 Fiber 链表中对应位置的节点</li><li><strong>key 和 type 都相同 → 复用，继续</strong> — 调用 <code>updateSlot</code>，复用并更新 props，指针前进</li><li><strong>key 不匹配 → 立即退出第一轮</strong> — 任意一侧 key 不一致，第一轮终止，进入第二轮处理剩余节点</li></ol><h3 id="第二轮-处理移动、新增、删除" tabindex="-1">第二轮：处理移动、新增、删除 <a class="header-anchor" href="#第二轮-处理移动、新增、删除" aria-label="Permalink to &quot;第二轮：处理移动、新增、删除&quot;">​</a></h3><ol><li><strong>把旧链表剩余节点存入 Map</strong> — 以 <code>key → Fiber</code> 或 <code>index → Fiber</code> 为索引，快速查找可复用节点（O(1)）</li><li><strong>遍历新列表剩余项</strong> — 在 Map 中查找对应 key： <ul><li>✅ 找到且 type 相同 → 复用，从 Map 移除</li><li>未找到 → 新建 Fiber（Placement 标记）</li></ul></li><li><strong>Map 中剩余的旧节点 → 全部删除</strong> — 遍历结束后，Map 中未被匹配的节点都是已删除的节点，打上 Deletion 标记</li></ol><h3 id="场景-a-顺序未变-仅-props-更新" tabindex="-1">场景 A：顺序未变，仅 props 更新 <a class="header-anchor" href="#场景-a-顺序未变-仅-props-更新" aria-label="Permalink to &quot;场景 A：顺序未变，仅 props 更新&quot;">​</a></h3><p>第一轮全部命中，无需进入第二轮。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>旧列表：  [A(key=&quot;a&quot;)] → [B(key=&quot;b&quot;)] → [C(key=&quot;c&quot;)]</span></span>
<span class="line"><span>新列表：  [A&#39;(key=&quot;a&quot;)] → [B&#39;(key=&quot;b&quot;)] → [C&#39;(key=&quot;c&quot;)]</span></span>
<span class="line"><span>结果：    ✅ 三个节点全部复用，无移动，仅更新 props</span></span></code></pre></div><h3 id="场景-b-列表末尾新增节点" tabindex="-1">场景 B：列表末尾新增节点 <a class="header-anchor" href="#场景-b-列表末尾新增节点" aria-label="Permalink to &quot;场景 B：列表末尾新增节点&quot;">​</a></h3><p>第一轮命中旧节点，第二轮处理新增。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>旧列表：  [A(key=&quot;a&quot;)] → [B(key=&quot;b&quot;)]</span></span>
<span class="line"><span>新列表：  [A&#39;(key=&quot;a&quot;)] → [B&#39;(key=&quot;b&quot;)] → [C(key=&quot;c&quot;)]</span></span>
<span class="line"><span>结果：     C 在旧 Map 中找不到，标记 Placement（插入）</span></span></code></pre></div><h3 id="场景-c-节点移动-最复杂" tabindex="-1">场景 C：节点移动（最复杂） <a class="header-anchor" href="#场景-c-节点移动-最复杂" aria-label="Permalink to &quot;场景 C：节点移动（最复杂）&quot;">​</a></h3><p>第二轮处理，需要 <code>lastPlacedIndex</code> 算法判断哪些节点需要移动。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>旧列表：  [A(i=0)] → [B(i=1)] → [C(i=2)] → [D(i=3)]</span></span>
<span class="line"><span>新列表：  [D(旧i=3)] → [A(旧i=0)] → [B(旧i=1)] → [C(旧i=2)]</span></span></code></pre></div><blockquote><p><strong>lastPlacedIndex 算法</strong>：React 追踪&quot;最后一个可不移动的旧节点索引&quot;。遍历时 D(3) 设为 lastPlacedIndex=3，后续 A(0)、B(1)、C(2) 的旧索引均 &lt; 3，说明它们需要被移动到 D 的后面 → 标记 Placement。</p></blockquote><blockquote><p><strong>lastPlacedIndex 核心思想</strong>：React 优先保持相对顺序不变的节点不动，对于在旧位置&quot;靠前&quot;却在新位置&quot;靠后&quot;的节点，打上移动标记。这样可以最小化真实 DOM 操作次数。</p></blockquote><hr><h2 id="六、key-的本质作用" tabindex="-1">六、key 的本质作用 <a class="header-anchor" href="#六、key-的本质作用" aria-label="Permalink to &quot;六、key 的本质作用&quot;">​</a></h2><p><code>key</code> 是 React Diff 算法在处理<strong>列表节点</strong>时，用来识别&quot;逻辑上相同的节点&quot;的唯一标识。它的本质是：<strong>让 Diff 算法在 O(n) 时间内，跨越索引位置找到可复用节点。</strong></p><h3 id="有-key-vs-无-key-对比" tabindex="-1">有 key vs 无 key 对比 <a class="header-anchor" href="#有-key-vs-无-key-对比" aria-label="Permalink to &quot;有 key vs 无 key 对比&quot;">​</a></h3><p><strong>场景：在列表头部插入新节点 Dave</strong></p><h4 id="❌-无-key-或用-index-作-key" tabindex="-1">❌ 无 key（或用 index 作 key） <a class="header-anchor" href="#❌-无-key-或用-index-作-key" aria-label="Permalink to &quot;❌ 无 key（或用 index 作 key）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>旧列表：  [Alice(i=0)] → [Bob(i=1)] → [Carol(i=2)]</span></span>
<span class="line"><span>新列表：  [Dave(i=0)]  → [Alice(i=1)] → [Bob(i=2)] → [Carol(i=3)]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按 index 对比：</span></span>
<span class="line"><span>  i=0: Alice ≠ Dave → 更新 ❌</span></span>
<span class="line"><span>  i=1: Bob ≠ Alice → 更新 ❌</span></span>
<span class="line"><span>  i=2: Carol ≠ Bob → 更新 ❌</span></span>
<span class="line"><span>  i=3: null → Carol → 新建 </span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：4 个节点全部重建/更新，状态全部丢失！</span></span></code></pre></div><h4 id="✅-有正确的-key-稳定唯一标识" tabindex="-1">✅ 有正确的 key（稳定唯一标识） <a class="header-anchor" href="#✅-有正确的-key-稳定唯一标识" aria-label="Permalink to &quot;✅ 有正确的 key（稳定唯一标识）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>旧列表：  [Alice(key=&quot;alice&quot;)] → [Bob(key=&quot;bob&quot;)] → [Carol(key=&quot;carol&quot;)]</span></span>
<span class="line"><span>新列表：  [Dave(key=&quot;dave&quot;)]   → [Alice(key=&quot;alice&quot;)] → [Bob(key=&quot;bob&quot;)] → [Carol(key=&quot;carol&quot;)]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>通过 key 映射：</span></span>
<span class="line"><span>  alice → 找到旧节点 → 复用 ✅</span></span>
<span class="line"><span>  bob   → 找到旧节点 → 复用 ✅</span></span>
<span class="line"><span>  carol → 找到旧节点 → 复用 ✅</span></span>
<span class="line"><span>  dave  → Map 中不存在 → 新建 ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：仅 1 个新建，3 个复用，状态全部保留！</span></span></code></pre></div><h3 id="key-使用原则" tabindex="-1">key 使用原则 <a class="header-anchor" href="#key-使用原则" aria-label="Permalink to &quot;key 使用原则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>✅ 应该这样做</th><th>❌ 不应该这样做</th></tr></thead><tbody><tr><td>使用数据的稳定唯一 ID（如数据库 ID、UUID）</td><td>使用数组 index 作 key（增删时顺序变化会引发错误复用）</td></tr><tr><td>同级兄弟节点间唯一即可（不需全局唯一）</td><td>使用 <code>Math.random()</code> 作 key（每次渲染都变，强制全量重建）</td></tr></tbody></table><hr><h2 id="七、首次挂载-vs-更新对比总结" tabindex="-1">七、首次挂载 vs 更新对比总结 <a class="header-anchor" href="#七、首次挂载-vs-更新对比总结" aria-label="Permalink to &quot;七、首次挂载 vs 更新对比总结&quot;">​</a></h2><h3 id="mount-vs-update-全流程对比" tabindex="-1">Mount vs Update 全流程对比 <a class="header-anchor" href="#mount-vs-update-全流程对比" aria-label="Permalink to &quot;Mount vs Update 全流程对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>首次挂载（Mount）</th><th>🔄 状态更新（Update）</th></tr></thead><tbody><tr><td><strong>触发来源</strong></td><td><code>ReactDOM.createRoot().render(&lt;App/&gt;)</code></td><td><code>setState</code> / <code>dispatch</code> / 父组件重渲染</td></tr><tr><td><strong>current 树</strong></td><td>不存在（为 null）</td><td>存在，提供对比基准</td></tr><tr><td><strong>Diff 操作</strong></td><td>无对比，直接 <code>createFiberFromElement</code> 全量创建</td><td><code>reconcileChildFibers</code> 对比新 Element 与旧 Fiber，决定复用或新建</td></tr><tr><td><strong>flags 标记</strong></td><td>所有节点都打上 <code>Placement</code>（需要插入 DOM）</td><td>仅标记实际变化的节点（Update / Placement / Deletion）</td></tr><tr><td><strong>effectList</strong></td><td>包含整棵树的所有节点</td><td>只包含有 flags 的节点（通常远少于全量）</td></tr><tr><td><strong>Commit 操作</strong></td><td>一次性将整棵 Fiber 树对应的 DOM 插入页面</td><td>按 effectList 最小化 DOM 操作</td></tr><tr><td><strong>生命周期</strong></td><td>触发 <code>componentDidMount</code> / <code>useEffect</code>（首次）</td><td>触发 <code>componentDidUpdate</code> / <code>useEffect</code>（cleanup + 重新执行）</td></tr></tbody></table><h3 id="两阶段-fiber-创建函数对比" tabindex="-1">两阶段 Fiber 创建函数对比 <a class="header-anchor" href="#两阶段-fiber-创建函数对比" aria-label="Permalink to &quot;两阶段 Fiber 创建函数对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>首次挂载</th><th>状态更新</th></tr></thead><tbody><tr><td><strong>调用函数</strong></td><td><code>mountChildFibers()</code></td><td><code>reconcileChildFibers()</code></td></tr><tr><td><strong>核心操作</strong></td><td><code>createFiberFromElement()</code></td><td><code>useFiber()</code> 或 <code>createFiberFromElement()</code></td></tr><tr><td><strong>副作用追踪</strong></td><td>不追踪（根节点除外），减少开销</td><td>追踪副作用，为变化节点打 flags</td></tr></tbody></table><blockquote><p>💡 这两个函数是同一套逻辑（<code>ChildReconciler</code>）用不同参数（<code>shouldTrackSideEffects</code>）创建的两个版本，这也是 React 源码中经典的&quot;闭包工厂&quot;模式。</p></blockquote><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">问题</th><th style="text-align:left;">答案</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Fiber 和 React Element 的关系？</strong></td><td style="text-align:left;">Element 是每次渲染临时生成的&quot;蓝图&quot;（不可变），Fiber 是持久的&quot;建筑实体&quot;，Reconciliation 就是用新蓝图更新建筑的过程。</td></tr><tr><td style="text-align:center;"><strong>双缓冲的意义？</strong></td><td style="text-align:left;">current 树服务当前屏幕，WIP 树在后台构建，互不干扰，Commit 阶段原子切换，避免用户看到中间态。</td></tr><tr><td style="text-align:center;"><strong>单节点 Diff 的核心？</strong></td><td style="text-align:left;">key 优先匹配，type 作为复用的最终判断；key 相同 type 不同时，全量重建，不保留状态。</td></tr><tr><td style="text-align:center;"><strong>多节点 Diff 的两轮含义？</strong></td><td style="text-align:left;">第一轮处理顺序不变的主流情况（贪心），第二轮用 Map 处理乱序移动/新增/删除。</td></tr><tr><td style="text-align:center;"><strong>为什么不能用 index 作 key？</strong></td><td style="text-align:left;">增删时 index 变化会导致错误复用（旧节点被当成不同节点的 key 映射），引发 UI 错乱和状态丢失。</td></tr><tr><td style="text-align:center;"><strong>Mount 和 Update 的本质区别？</strong></td><td style="text-align:left;">Mount 时 current 树为 null，全量创建；Update 时有旧 Fiber 可对比，最小化变更。</td></tr></tbody></table><hr><h2 id="🎤-面试回答完整版-10分版" tabindex="-1">🎤 面试回答完整版（10分版） <a class="header-anchor" href="#🎤-面试回答完整版-10分版" aria-label="Permalink to &quot;🎤 面试回答完整版（10分版）&quot;">​</a></h2><h3 id="第一段-先定性" tabindex="-1">第一段：先定性 <a class="header-anchor" href="#第一段-先定性" aria-label="Permalink to &quot;第一段：先定性&quot;">​</a></h3><p>Fiber 是 React 16 为了解决两个问题而引入的重写——一是传统递归 Diff 不可中断，导致长任务阻塞渲染；二是缺乏优先级调度能力，高优交互要给低优数据渲染让路。</p><hr><h3 id="第二段-数据结构怎么支撑可中断" tabindex="-1">第二段：数据结构怎么支撑可中断 <a class="header-anchor" href="#第二段-数据结构怎么支撑可中断" aria-label="Permalink to &quot;第二段：数据结构怎么支撑可中断&quot;">​</a></h3><p>核心是把树形结构变成链表。每个 Fiber 节点有三个指针——<code>return</code> 指向父节点、<code>child</code> 指向第一个子节点、<code>sibling</code> 指向下一个兄弟节点。整棵树就被表达成了一个单链表。传统递归 Diff 像函数调用栈，一旦入栈就必须全部执行完才能退出。Fiber 链表让 React 可以在每处理完一个节点后，检查时间切片是否用完、是否有更高优先级的更新进来。如果有，就暂停，把控制权还给浏览器去渲染——下次再从暂停的那个节点继续。这就好比翻一本书：递归是一次性从头翻到尾，中间不能停；Fiber 是每翻一页就抬头看一眼——有没有更重要的事要处理。</p><hr><h3 id="第三段-双缓冲——为什么-wip-树可以随便丢弃" tabindex="-1">第三段：双缓冲——为什么 WIP 树可以随便丢弃 <a class="header-anchor" href="#第三段-双缓冲——为什么-wip-树可以随便丢弃" aria-label="Permalink to &quot;第三段：双缓冲——为什么 WIP 树可以随便丢弃&quot;">​</a></h3><p>React 维护了两棵树——current 树对应屏幕上正在显示的内容，workInProgress 树描述下一帧。每次更新的 Render 阶段，React 基于 current 树 clone 出一棵新的 WIP 树来构建。这里有个关键点：WIP 树本质是一份草稿。如果构建过程中被更高优先级的更新打断，已构建的部分直接废弃，重新从新的根节点开始构建。因为 current 树没变，屏幕上的内容不会闪烁或错乱。当 WIP 树构建完成后，Commit 阶段 <code>FiberRoot.current</code> 指针做一次原子切换，指向新的 WIP 树。原来的 current 树成为下一次的&quot;旧树&quot;，被回收或复用。所以 WIP 树被废弃不是&quot;浪费&quot;——它恰恰是双缓冲设计的核心意图：宁可重来，也不要让用户看到中间状态。</p><hr><h3 id="第四段-协调流程怎么跑" tabindex="-1">第四段：协调流程怎么跑 <a class="header-anchor" href="#第四段-协调流程怎么跑" aria-label="Permalink to &quot;第四段：协调流程怎么跑&quot;">​</a></h3><p>Render 阶段分为两个子阶段：beginWork 向下、completeWork 向上。beginWork 从根节点入手，判断节点类型——函数组件就调用函数体执行 hooks，类组件就调 render()，DOM 节点就直接处理 props。然后调 reconcileChildren 做 Diff，生成子 Fiber 链表，接着继续深入第一个子节点。completeWork 到达叶子节点后开始回溯，对 DOM 节点在这一步创建或更新 DOM 实例，同时把有副作用的节点通过 effectList 逐级向上收集。整个 Render 阶段不操作真实 DOM，只做标记和收集。Commit 阶段直接拿着根节点上的 effectList 清单执行，所以很快。</p><hr><h3 id="第五段-diff-策略——面试核心" tabindex="-1">第五段：Diff 策略——面试核心 <a class="header-anchor" href="#第五段-diff-策略——面试核心" aria-label="Permalink to &quot;第五段：Diff 策略——面试核心&quot;">​</a></h3><p>React 的 Diff 基于三个假设：只做同级比较、类型不同直接重建、key 标识节点身份。这三个假设保证了 O(n) 的时间复杂度。单节点 Diff：key 优先于 type。key 不同直接认为不是同一个节点，跳过；key 相同再判断 type——type 也相同就复用，type 不同就删除旧节点及其所有兄弟，全新创建。多节点 Diff 是两轮遍历。第一轮从头按索引顺序对比，key 和 type 都匹配就复用，遇到不匹配立即退出。大多数场景（顺序不变、仅更新 props）第一轮就全部命中，直接结束。这是针对&quot;实际项目中 90% 的更新都是顺序不变的&quot;做的贪心优化，也是 React 不用 LCS 算法的原因——LCS 最坏 O(n²)，而且大多数场景的收益为 0。第二轮把旧链表剩余节点以 key 为索引放入 Map，遍历新列表在 Map 中查找。找到就复用，找不到就新建。最后 Map 中剩下的节点全部标记删除。节点移动的判断依赖 lastPlacedIndex 算法——记录最后一个不需要移动的节点在旧列表中的索引，后续节点的旧索引如果小于这个值，说明它在新列表里被移到了前面，标记为需要移动。</p><hr><h3 id="第六段-key-的本质——收束到工程实践" tabindex="-1">第六段：key 的本质——收束到工程实践 <a class="header-anchor" href="#第六段-key-的本质——收束到工程实践" aria-label="Permalink to &quot;第六段：key 的本质——收束到工程实践&quot;">​</a></h3><p>没有 key，Diff 只能按索引对比——在列表头部插入一个节点，后面所有节点的索引都变了，导致全部重建。这只是性能问题。更严重的是有状态的子组件——比如每个列表项里有一个 input，用户输入了内容。用 index 作 key，头部插入时，原来输入框的状态会被错误地复用给另一个列表项，导致 UI 错乱和数据丢失。所以 key 的核心作用不是&quot;性能优化&quot;，而是保持节点身份的稳定性——让 React 在索引变化后仍然能认出&quot;这是之前那个组件&quot;，保留它的状态。最佳实践：用数据的稳定唯一 ID，不用 index，不用随机数。</p><hr><h3 id="第七段-点睛收尾" tabindex="-1">第七段：点睛收尾 <a class="header-anchor" href="#第七段-点睛收尾" aria-label="Permalink to &quot;第七段：点睛收尾&quot;">​</a></h3><p>总结：Fiber 用链表结构解决了递归不可中断的问题；双缓冲保障了可中断的安全边界；两轮遍历的 Diff 在 O(n) 内处理了 90% 的常规更新；key 保证了组件身份在索引变化时的稳定性。理解 Fiber，本质上就是理解了 React 对『如何在浏览器主线程上优雅地执行大量计算』这个问题的答案。</p><p><strong>三个层次一句话总览：</strong></p><table tabindex="0"><thead><tr><th>层次</th><th>核心设计</th><th>解决了什么</th></tr></thead><tbody><tr><td>数据结构层</td><td>链表（return / child / sibling）</td><td>递归不可中断 → 可中断可恢复</td></tr><tr><td>设计模式层</td><td>双缓冲（current ↔ WIP）</td><td>可中断导致中间状态不可见 → 草稿树可丢弃</td></tr><tr><td>算法层</td><td>两轮 Diff（贪心 + Map）</td><td>O(n²) → O(n)，且 90% 场景第一轮结束</td></tr></tbody></table><p><strong>单节点 vs 多节点 Diff 对比：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>单节点 Diff</th><th>多节点 Diff（第一轮）</th><th>多节点 Diff（第二轮）</th></tr></thead><tbody><tr><td>匹配依据</td><td>key 优先于 type</td><td>按索引顺序对比 key + type</td><td>key 查 Map</td></tr><tr><td>失败处理</td><td>直接全部重建</td><td>退出第一轮，进入第二轮</td><td>找不到则新建，剩余则删除</td></tr><tr><td>命中场景</td><td>只有一个子节点</td><td>列表顺序不变（90% 常见）</td><td>列表增删、顺序变动</td></tr><tr><td>移动判断</td><td>无需</td><td>无需（位置不变）</td><td>lastPlacedIndex 算法</td></tr></tbody></table><p><strong>key 的三种错误用法对比：</strong></p><table tabindex="0"><thead><tr><th>用法</th><th>后果</th><th>严重性</th></tr></thead><tbody><tr><td><code>key={index}</code></td><td>列表头部插入时，有状态组件状态错位</td><td>⚠️ 数据丢失</td></tr><tr><td><code>key={Math.random()}</code></td><td>每次渲染都重建全部节点</td><td>❌ 性能崩溃</td></tr><tr><td><code>key={稳定唯一ID}</code></td><td>React 能正确识别节点身份</td><td>✅ 最佳实践</td></tr></tbody></table>`,112)])])}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
